12	async function readJson(req: IncomingMessage): Promise<Record<string, unknown>> {
13	  let raw = "";
14	  for await (const chunk of req) raw += chunk;
15	  try {
16	    return JSON.parse(raw || "{}");
17	  } catch {
18	    return {};
19	  }
20	}
