22	export async function handle(req: IncomingMessage, res: ServerResponse) {
23	  const url = new URL(req.url ?? "/", "http://localhost");
24	  const id = Number(url.pathname.match(/^\/api\/todos\/(\d+)$/)?.[1]);
25	
26	  if (req.method === "GET" && url.pathname === "/") {
27	    res.writeHead(200, { "content-type": "text/html" });
28	    res.end(await readFile(new URL("../public/index.html", import.meta.url)));
29	    return;
30	  }
31	  if (req.method === "GET" && url.pathname === "/api/todos") return send(res, 200, store.list());
32	  if (req.method === "POST" && url.pathname === "/api/todos") {
33	    const { title } = await readJson(req);
34	    if (typeof title !== "string" || !title.trim())
35	      return send(res, 400, { error: "title is required" });
36	    return send(res, 201, store.add(title));
37	  }
38	  if (req.method === "PATCH" && id) {
39	    const todo = store.toggle(id);
40	    return todo ? send(res, 200, todo) : send(res, 404, { error: "not found" });
41	  }
42	  if (req.method === "DELETE" && id) {
43	    return store.remove(id) ? send(res, 204) : send(res, 404, { error: "not found" });
44	  }
45	  send(res, 404, { error: "not found" });
46	}
