test("POST /api/todos without a title is a 400", async () => {
  const res = await fetch(`${base}/api/todos`, { method: "POST", body: "{}" });
  assert.equal(res.status, 400);
});

async function create(title = "Original") {
  const res = await fetch(`${base}/api/todos`, { method: "POST", body: JSON.stringify({ title }) });
  return res.json();
}

const patch = (id: number, body?: string) =>
  fetch(`${base}/api/todos/${id}`, { method: "PATCH", body });

test("PATCH with a title renames and leaves done alone", async () => {
  const todo = await create();
  const res = await patch(todo.id, JSON.stringify({ title: "  New name " }));
  assert.equal(res.status, 200);
  assert.deepEqual(await res.json(), { ...todo, title: "New name" });
});

test("PATCH with an empty body or {} toggles done", async () => {
  const todo = await create();
  const res = await patch(todo.id);
  assert.equal(res.status, 200);
  assert.equal((await res.json()).done, true);
  assert.equal((await (await patch(todo.id, "{}")).json()).done, false);
});

test("PATCH with a bad title is a 400 and changes nothing", async () => {
  const todo = await create();
  for (const title of ["", "  ", 5, null]) {
    const res = await patch(todo.id, JSON.stringify({ title }));
    assert.equal(res.status, 400);
    assert.deepEqual(await res.json(), { error: "title is required" });
  }
  const todos = await (await fetch(`${base}/api/todos`)).json();
  assert.deepEqual(todos.find((t: { id: number }) => t.id === todo.id), todo);
});

test("PATCH ignores fields other than title", async () => {
  const todo = await create();
  const res = await patch(todo.id, JSON.stringify({ title: "x", id: 999, done: true, foo: 1 }));
  assert.equal(res.status, 200);
  assert.deepEqual(await res.json(), { ...todo, title: "x" });
  const todos = await (await fetch(`${base}/api/todos`)).json();
  assert.deepEqual(todos.find((t: { id: number }) => t.id === todo.id), { ...todo, title: "x" });
});

test("PATCH with a title on an unknown id is a 404", async () => {
  const res = await patch(99999, JSON.stringify({ title: "x" }));
  assert.equal(res.status, 404);
});

